t=p.read_text()
start=t.index('function runtimeEnv(overrides = {}) {')
end=t.index("\ntest('positive ids", start)
fixture='''function runtimeEnv(overrides = {}) {\n  return {\n    APP_NAME: 'MIRA-TV', MIRA_TV_VERSION: '1.0.0.1', NODE_ENV: 'test', HOST: '127.0.0.1', PORT: '8080', MIRA_TV_DOMAIN: 'mira.example.test',\n    SESSION_SECRET: 's'.repeat(48), SESSION_TTL_HOURS: '12', SECURE_COOKIES: 'false',\n    DEVICE_ACTIVATION_TTL_MINUTES: '10', DEVICE_ACTIVATION_POLL_SECONDS: '2', DEVICE_ACTIVATION_MAX_ATTEMPTS: '20',\n    DEVICE_ACTIVATION_WINDOW_MINUTES: '10', DEVICE_ACTIVATION_LIMITER_MAX_ENTRIES: '10000', DEVICE_ACTIVATION_CLEANUP_MINUTES: '15', DEVICE_ACTIVATION_RETENTION_HOURS: '24',\n    DEVICE_SESSION_TTL_DAYS: '365', DEVICE_HEARTBEAT_WRITE_SECONDS: '60', PLAYER_FALLBACK_POLL_SECONDS: '60',\n    PLAYER_LOG_BATCH_SIZE: '100', PLAYER_LOG_LOCAL_MAX_ENTRIES: '5000', PLAYER_LOG_LOCAL_MAX_BYTES: '10485760',\n    EVENT_JOURNAL_RETENTION_DAYS: '30', EVENT_JOURNAL_MAX_ENTRIES: '5000',\n    PASSWORD_MIN_LENGTH: '10', PASSWORD_MAX_LENGTH: '32', GENERATED_PASSWORD_LENGTH: '10',\n    LOGIN_MAX_ATTEMPTS: '8', LOGIN_IP_MAX_ATTEMPTS: '32', LOGIN_WINDOW_MINUTES: '15', LOGIN_LIMITER_MAX_ENTRIES: '500',\n    JSON_BODY_MAX_BYTES: '65536', MENU_DRAFT_MAX_BYTES: '49152', SCREEN_SOURCE_MAX_BYTES: '12582912',\n    DASHBOARD_REFRESH_MIN_SECONDS: '15', DASHBOARD_REFRESH_MAX_SECONDS: '300', SCREEN_MAX_WIDTH: '1920', SCREEN_MAX_HEIGHT: '1080', IMAGE_MAX_PIXELS: '40000000',\n    SITE_ASSETS_ROOT: '/tmp/mira-tv-assets', SITE_LOGO_MAX_BYTES: '2097152', SITE_FAVICON_MAX_BYTES: '524288', SCREEN_BACKGROUND_MAX_BYTES: '20971520', ENTITY_ASSET_MAX_BYTES: '104857600', HEALTH_READINESS_CACHE_MS: '2000',\n    POSTGRES_HOST: 'db', POSTGRES_PORT: '5432', POSTGRES_DB: 'mira_tv', POSTGRES_USER: 'mira_tv', POSTGRES_PASSWORD: 'p'.repeat(32), POSTGRES_POOL_MAX: '5', POSTGRES_CONNECTION_TIMEOUT_MS: '5000', POSTGRES_IDLE_TIMEOUT_MS: '30000',\n    SEED_DEMO_DATA: 'false', ...overrides\n  };\n}\n'''
t=t[:start]+fixture+t[end:]
t=t.replace("assert.throws(() => loadConfig(runtimeEnv({ SFTP_API_TIMEOUT_MS: '5000ms' })), /SFTP_API_TIMEOUT_MS.*целым числом/);\n  ", "")
